type client struct {
    mu      sync.Mutex
    pending map[string]chan *Reply
}

func (c *client) Call(ctx context.Context, body string) (*Reply, error) {
    id := uuid.NewString()
    ch := make(chan *Reply, 1)           // buffered: the reader never blocks
    c.mu.Lock(); c.pending[id] = ch; c.mu.Unlock()
    defer func() { c.mu.Lock(); delete(c.pending, id); c.mu.Unlock() }()
    if err := c.send(&Request{ID: id, Body: body}); err != nil { return nil, err }
    select {
    case r := <-ch:
        return r, nil
    case <-ctx.Done():                    // deadline from context.WithTimeout
        return nil, ctx.Err()
    }
}
